import{_ as a,o as e,c as s,a4 as d}from"./chunks/framework.BRzJ4ijD.js";const u=JSON.parse('{"title":"1. 顺序 vs 链接: CPU 视角下两种物理化","description":"","frontmatter":{},"headers":[],"relativePath":"_meta/contiguous-vs-linked.md","filePath":"_meta/contiguous-vs-linked.md","lastUpdated":1788475713000}'),n={name:"_meta/contiguous-vs-linked.md"};function o(i,t,r,l,c,p){return e(),s("div",null,[...t[0]||(t[0]=[d(`<h1 id="_1-顺序-vs-链接-cpu-视角下两种物理化" tabindex="-1">1. 顺序 vs 链接: CPU 视角下两种物理化 <a class="header-anchor" href="#_1-顺序-vs-链接-cpu-视角下两种物理化" aria-label="Permalink to &quot;1. 顺序 vs 链接: CPU 视角下两种物理化&quot;">​</a></h1><h2 id="一句话" tabindex="-1">一句话 <a class="header-anchor" href="#一句话" aria-label="Permalink to &quot;一句话&quot;">​</a></h2><p>数据结构教科书里有十几种结构, 但落到物理内存上只有两种选项: <strong>顺序</strong> (contiguous) 和 <strong>链接</strong> (linked). 顺序赢在 cache locality 和 SIMD 吞吐, 链接赢在 O(1) splice 和迭代器稳定性. 这两种物理化在 CPU 视角、运行时视角、网络协议视角、磁盘视角都反复出现 —— <strong>理解了&quot;顺序 vs 链接&quot;这一对双胞胎, 你就理解了数据结构差异的 80%</strong>.</p><h2 id="思想链" tabindex="-1">思想链 <a class="header-anchor" href="#思想链" aria-label="Permalink to &quot;思想链&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>工程问题: 为什么 std::vector 几乎总是比 std::list 快?</span></span>
<span class="line"><span>  └─► 数学对象必须选一个物理化身</span></span>
<span class="line"><span>        └─► 顺序: addr[i] = base + i * sizeof(T), 地址可以直接算出来</span></span>
<span class="line"><span>        └─► 链接: node-&gt;next 逐个追指针, 地址不可预测</span></span>
<span class="line"><span>  └─► 硬件三层把差距放大成数量级</span></span>
<span class="line"><span>        └─► cache: 顺序流一次取回 64B line 全是有用数据;</span></span>
<span class="line"><span>                   链表节点散落各处, 指针 + 有效负载挤在一起</span></span>
<span class="line"><span>        └─► prefetcher: 固定 stride 的顺序流是理想客户; 指针追逐无法预取</span></span>
<span class="line"><span>        └─► SIMD: AVX-512 一条 load 吃 16 个 int; 链表喂不进向量寄存器</span></span>
<span class="line"><span>  └─► 但链接买到了两样东西: O(1) splice + 迭代器稳定性</span></span>
<span class="line"><span>        └─► 选型问题归结为一句: &quot;你要局部性, 还是要稳定性?&quot; —— 其余全是推论</span></span></code></pre></div><h2 id="第一站-物理化" tabindex="-1">第一站: 物理化 <a class="header-anchor" href="#第一站-物理化" aria-label="Permalink to &quot;第一站: 物理化&quot;">​</a></h2><p>数据结构本身是数学对象:</p><ul><li>数组 = 索引到值的有限映射;</li><li>链表 = 头 + 尾组成的可拼接序列;</li><li>二叉树 = 节点 + 左右孩子组成的多级结构;</li><li>哈希表 = 函数 (hash) → 槽 + (比较) 的组合.</li></ul><p>但<strong>计算机必须给数学对象一个物理化身</strong>: 内存的字节怎么排布、指针怎么连、cache 怎么预取. 这一步 &quot;数学对象 → 物理化身&quot; 的选择几乎只有两条路:</p><h3 id="选项-a-顺序-contiguous" tabindex="-1">选项 A: 顺序 (contiguous) <a class="header-anchor" href="#选项-a-顺序-contiguous" aria-label="Permalink to &quot;选项 A: 顺序 (contiguous)&quot;">​</a></h3><p>把所有元素紧排到连续内存, 用偏移量 i 找元素: <code>addr[i] = base + i * sizeof(T)</code>.</p><ul><li><strong>代表</strong>: 数组、动态数组、堆、CSR 邻接表、B+ 树页、SIMD 缓冲、SSD page;</li><li><strong>优势</strong>: O(1) 索引、cache 极友好、SIMD 可并行、零指针开销;</li><li><strong>代价</strong>: 大小固定 / 改大小要扩容、中间插入代价 O(n)、迭代器失效.</li></ul><h3 id="选项-b-链接-linked" tabindex="-1">选项 B: 链接 (linked) <a class="header-anchor" href="#选项-b-链接-linked" aria-label="Permalink to &quot;选项 B: 链接 (linked)&quot;">​</a></h3><p>每个元素自带一个或多个指针指向下/上一个元素, 内存可以散乱分布.</p><ul><li><strong>代表</strong>: 链表、树、跳表、哈希桶链、<code>std::map</code> (红黑树);</li><li><strong>优势</strong>: O(1) splice (已知指针时)、迭代器稳定、动态扩容零拷贝;</li><li><strong>代价</strong>: 每元素 +8B (或更多) 指针开销、cache miss 风暴、几乎无法 SIMD.</li></ul><h2 id="同一抽象的两条物化路径" tabindex="-1">同一抽象的两条物化路径 <a class="header-anchor" href="#同一抽象的两条物化路径" aria-label="Permalink to &quot;同一抽象的两条物化路径&quot;">​</a></h2><p>数学抽象层面, 它们是<strong>一对对偶</strong>: 同一个抽象有两条工程化路径. 下面从 CPU、运行时、协议、磁盘四处各举一对实例:</p><h3 id="cpu-层" tabindex="-1">CPU 层 <a class="header-anchor" href="#cpu-层" aria-label="Permalink to &quot;CPU 层&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>顺序: SSE/AVX SIMD — 16/32/64 字节一条 load 装多个元素 ≈ 1 cycle / 8 个元素</span></span>
<span class="line"><span>链接: 间接寻址 (load 指针再 load 数据) ≈ 10+ cycle / 元素</span></span></code></pre></div><p>CPU 在 SIMD 上一次处理的就是&quot;一段顺序&quot;. &quot;链接&quot; 在 CPU 层是被惩罚的代名词 —— 链接破坏 prefetcher 的 stride 模型.</p><h3 id="内存模型层-运行时" tabindex="-1">内存模型层 (运行时) <a class="header-anchor" href="#内存模型层-运行时" aria-label="Permalink to &quot;内存模型层 (运行时)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>顺序: std::vector / Go slice / Python list 内部 = 一段连续字节.</span></span>
<span class="line"><span>链接: std::list / intrusive_list / dict overflow bucket 链.</span></span></code></pre></div><p><code>std::vector::iterator</code> 在扩容时失效 (底层基地址换了); <code>std::list::iterator</code> 在 erase 之后对其他节点仍然有效 —— <strong>这就是 &quot;链接&quot; 的标志特征</strong>.</p><h3 id="网络协议层" tabindex="-1">网络协议层 <a class="header-anchor" href="#网络协议层" aria-label="Permalink to &quot;网络协议层&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>顺序: TCP 字节流 — 数据按序到达, 滑动窗口按 sequence 号推进</span></span>
<span class="line"><span>链接: IP 路由的 next-hop 链 — 数据包一跳一跳地走</span></span></code></pre></div><p>TCP 是 sequential 接收, IP 是 hop-by-hop 路由 —— 这是网络栈里同型的两个层级 (详见 <a href="./../networking/tcp/handshake">三次握手与滑动窗口</a>).</p><h3 id="磁盘与日志层" tabindex="-1">磁盘与日志层 <a class="header-anchor" href="#磁盘与日志层" aria-label="Permalink to &quot;磁盘与日志层&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>顺序: WAL / LSM-Tree / Kafka append-only — 顺序写可达 GB/s</span></span>
<span class="line"><span>链接: inode / extent tree / B+ 树内部节点</span></span></code></pre></div><p>LSM-Tree 把&quot;顺序写&quot;做到极致 (单段顺序追加), B+ 树把&quot;范围查询&quot;做到极致 (叶子链接 + 内部有序). <strong>LSM 与 B+ 都在&quot;一棵树&quot;上</strong>, 但 LSM 把&quot;顺序&quot;放在 IO 层, B+ 把&quot;顺序&quot;放在内存层 —— 这就是同一抽象不同物化的对偶 (分别见 <a href="./../databases/indexing/lsm">LSM-Tree 与 SSTable</a> 与 <a href="./../databases/indexing/btree">B+ 树索引</a>).</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>这对对偶在磁盘层还有一个直接后果: SSD 最怕随机小写, 所以 LSM 的&quot;顺序追加&quot;天然对 SSD 友好, 而 B+ 树的随机页写只能靠 FTL 兜底——写放大因此差出数倍, 量化分析见 <a href="./../computer-arch/ssd-storage">存储硬件: NAND Flash / SSD FTL</a>.</p></div><h2 id="怎么决定选哪种" tabindex="-1">怎么决定选哪种? <a class="header-anchor" href="#怎么决定选哪种" aria-label="Permalink to &quot;怎么决定选哪种?&quot;">​</a></h2><p>业务真的需要 <strong>迭代器稳定性 / splice / 已知指针位置的 O(1) 操作</strong> ⇒ 链接. 否则, <strong>选顺序</strong>.</p><p>一个简单决策表:</p><table tabindex="0"><thead><tr><th>需求特征</th><th>推荐物理化</th></tr></thead><tbody><tr><td>批量随机访问</td><td>顺序</td></tr><tr><td>中间频繁插入 (无已知指针)</td><td>顺序 + 二分定位后批量搬移</td></tr><tr><td>中间频繁插入 (已知指针)</td><td>链接</td></tr><tr><td>大空间扩容 + 容量不可预测</td><td>顺序动态数组</td></tr><tr><td>大空间扩容 + 容量可限定</td><td>顺序 ring buffer</td></tr><tr><td>跨多线程需要稳定迭代器</td><td>顺序 <code>std::deque</code> 或链接</td></tr><tr><td>范围扫描</td><td>顺序 (任何 SIMD 友好的形态)</td></tr><tr><td>高 IO 顺序写</td><td>LSM (顺序物化的工程化版本)</td></tr></tbody></table><h2 id="工程的折衷-跨层同构" tabindex="-1">工程的折衷: 跨层同构 <a class="header-anchor" href="#工程的折衷-跨层同构" aria-label="Permalink to &quot;工程的折衷: 跨层同构&quot;">​</a></h2><p>这一段的中心观点: <strong>&quot;顺序 / 链接&quot; 这对对偶在不同层次反复出现</strong>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>软件层: 数组 vs 链表</span></span>
<span class="line"><span>OS 层:  page cache 顺序读 vs fsync 散写</span></span>
<span class="line"><span>网络层: TCP 顺序字节流 vs IP 逐跳路由</span></span>
<span class="line"><span>硬件层: SIMD packed op vs 间接寻址</span></span></code></pre></div><p><strong>底层是同一抽象的两个方向物化</strong>: 在同一规模上, &quot;顺序&quot; 总在 cache、SIMD、batch 上占优; &quot;链接&quot; 总换来 splice、稳定迭代器、跨层 indirection.</p><h2 id="多语言对比" tabindex="-1">多语言对比 <a class="header-anchor" href="#多语言对比" aria-label="Permalink to &quot;多语言对比&quot;">​</a></h2><p>语言标准库对 &quot;顺序 / 链接&quot; 的默认提供非常不同:</p><table tabindex="0"><thead><tr><th>语言</th><th>主顺序容器</th><th>主链接容器</th><th>备选</th></tr></thead><tbody><tr><td>C++</td><td><code>std::vector</code></td><td><code>std::list</code></td><td><code>std::deque</code> 折中</td></tr><tr><td>Rust</td><td><code>Vec&lt;T&gt;</code></td><td>标准库故意不内置</td><td><code>Box&lt;Node&gt;</code> 自实现</td></tr><tr><td>Go</td><td><code>[]T</code> 切片</td><td><code>container/list</code> 通用</td><td><code>ring</code> 环形缓冲</td></tr><tr><td>Python</td><td><code>list</code></td><td>无纯链接类型</td><td><code>deque</code> 分块链接</td></tr><tr><td>Java</td><td><code>ArrayList</code></td><td><code>LinkedList</code></td><td><code>ArrayDeque</code> 通常更优</td></tr><tr><td>JS</td><td><code>Array</code> 紧排模式</td><td>无内置</td><td>对象模拟链表</td></tr></tbody></table><p>特别提到 Rust 故意不在标准库内置链表 —— 这是语言设计哲学的表态: <strong>现代默认应该选顺序, 链接只在确需时引入</strong>. 这个决定不是性能微调, 而是把数据结构物理化的选择<strong>显式化</strong> —— 你真需要链表就得自己写或者引第三方 crate. 这反而强迫你<strong>思考清楚需求</strong>.</p><h2 id="fpga-视角" tabindex="-1">FPGA 视角 <a class="header-anchor" href="#fpga-视角" aria-label="Permalink to &quot;FPGA 视角&quot;">​</a></h2><p>在 FPGA 上, 这种对偶更明显:</p><ul><li><strong>顺序 BRAM</strong>: 单地址空间, 给 base addr + offset 即可寻址, 等价软件的数组;</li><li><strong>链式 BRAM</strong>: 链表节点存下一节点地址, 需要在 BRAM 上模拟指针解引用, 一次跳转延迟几十 cycle.</li></ul><p>数据流图 (DFG) 加速器里常见的 shift register / systolic array 就是顺序物化的&quot;流水&quot;; 而链式描述必须在 BRAM 上模拟 ptr. 这就是 FPGA 上<strong>几乎所有高速数据通路都选顺序物化</strong>的原因.</p><h2 id="这一章带走的东西" tabindex="-1">这一章带走的东西 <a class="header-anchor" href="#这一章带走的东西" aria-label="Permalink to &quot;这一章带走的东西&quot;">​</a></h2><ul><li><strong>物理化几乎只有顺序 vs 链接两条路, 绝大多数数据结构都是这两者之一或其组合</strong>;</li><li>顺序赢 cache + SIMD + indexing, 链接赢 splice + 迭代器稳定性;</li><li>网络层、OS 层、硬件层都有这种对偶同构;</li><li>选哪种不只看操作复杂度 O(), 更看 cache、并发、迭代器稳定性;</li><li>Rust 标准库不内置 list 是一种哲学态度: 显式选择物理化.</li></ul><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>&quot;链表插入 O(1)&quot; 只在<strong>已知指针</strong>时成立, 先找到插入点仍然是 O(n). 而 vector 中部插入虽然要搬移元素, 但那是一次 SIMD 友好的 <code>memmove</code>, 元素数不大时实测往往比 list 更快——不要用复杂度记号代替 benchmark, 两者的基准对比见 <a href="./../dsa/structures/array">数组与动态数组</a> 与 <a href="./../dsa/structures/linked-list">链表: 单链/双链/跳表</a>.</p></div><h2 id="一页速查" tabindex="-1">一页速查 <a class="header-anchor" href="#一页速查" aria-label="Permalink to &quot;一页速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>顺序 (contiguous)</th><th>链接 (linked)</th></tr></thead><tbody><tr><td>寻址</td><td><code>base + i * sizeof(T)</code>, O(1)</td><td>追指针, O(n)</td></tr><tr><td>cache / prefetcher</td><td>友好, stride 固定</td><td>miss 风暴, 无法预取</td></tr><tr><td>SIMD</td><td>可向量化</td><td>喂不进向量寄存器</td></tr><tr><td>中间插删</td><td>O(n) 批量搬移</td><td>已知指针时 O(1)</td></tr><tr><td>迭代器稳定性</td><td>扩容即失效</td><td>erase 其他节点仍有效</td></tr><tr><td>空间开销</td><td>只有元素本身</td><td>每节点多 1-2 个指针</td></tr><tr><td>代表结构</td><td>array / vector / deque / 堆 / CSR / B+ 叶子</td><td>list / 树 / 跳表 / 哈希桶链</td></tr><tr><td>跨层同构</td><td>WAL · LSM · TCP 字节流 · SIMD load</td><td>inode · extent · IP 逐跳 · 间接寻址</td></tr></tbody></table><p>下一篇: <a href="./amortized-vs-worst">2. 摊还 vs 最坏: 工程常数与硬实时的张力</a>。</p>`,52)])])}const g=a(n,[["render",o]]);export{u as __pageData,g as default};
